lemma.raw:
\label{lem:rank p}
For $T\in\mathscr{V}$, 
$\mathrm{rank} T=p$ if and only if $\dim U(\mu(\sigma(T)))=p$.

\label{lem:key}
Let $y$ be an indeterminate and $a_1,\ldots, a_{m-1}\in\mathbb{C}$.
Then the following conditions are equivalent,
where $V_a(I)$ denotes the affine variety defined by an ideal $I$.
\begin{enumerate}
\item
$(a_1,\ldots, a_{m-1},-1)\in V_a(I_n(M(\xxx,A)))$.
\item
$y^{m-1}-a_{m-1}y^{m-2}-\cdots-a_2y-a_1$ is a factor of $y^u+1$.
\end{enumerate}

\label{lem:non full rank}
Under the notation above, the following  conditions are equivalent.
\begin{enumerate}
\item
\label{item:rank less than n}
$\mathrm{rank} N<n$.
\item
\label{item:minors vanish}
$[i,m,m+1,\ldots,u]_N=0$ for $1\leq i\leq m-1$.
\item
\label{item:lambda u+1}
$\lambda_{u+t}=0$ for $1\leq t\leq m-2$ and $\lambda_{u+m-1}=-1$.
\item
\label{item:rec u}
$\lambda_{u+t}=-\lambda_t$ for $t\geq 1$.
\item
\label{item:yu}
$y^u+1\in\mathscr{I}(\{\lambda_t\}_{t\geq 1})$.
\end{enumerate}

